import {notFound} from 'next/navigation';
import {prisma} from '@/lib/prisma';
import Link from 'next/link';
export const dynamic='force-dynamic';
export default async function Storefront({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const vendor=await prisma.vendorProfile.findFirst({where:{storeSlug:slug,isVerified:true,isSuspended:false},include:{products:{where:{status:'PUBLISHED',vendorStatus:{in:['APPROVED','PUBLISHED']}},orderBy:{createdAt:'desc'},take:50}}});if(!vendor)notFound();return <main className="site-shell py-12"><div className="mx-auto max-w-6xl"><p className="eyebrow">VERIFIED SELLER</p><h1 className="mt-3 text-4xl font-bold">{vendor.storeName}</h1><p className="mt-4 max-w-2xl text-slate-400">{vendor.storeDescription}</p><div className="mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{vendor.products.map(product=><Link href={`/templates/${product.slug}`} className="admin-panel" key={product.id}><h2 className="font-semibold">{product.name}</h2><p className="mt-2 text-sm text-slate-400">{product.priceMmk.toLocaleString()} MMK</p></Link>)}</div>{!vendor.products.length&&<div className="admin-panel mt-8">This seller has no published products yet.</div>}</div></main>}
